import type { FC } from 'react';
import { useLocation } from "react-router-dom";
import { useEffect } from "react";

const NotFound: FC = () => {
  const location = useLocation();

  useEffect(() => {
    console.error(
      "404 Error: User attempted to access non-existent route:",
      location.pathname
    );
  }, [location.pathname]);

  return (
    <div className="min-h-screen flex items-center justify-center bg-background px-4">
      <div className="text-center">
        <h1 className="text-7xl md:text-8xl font-display font-bold mb-4 text-accent">
          404
        </h1>
        <p className="text-xl text-muted-foreground mb-8">Oops! This page drifted off the map.</p>
        <a
          href="/"
          className="inline-block px-6 py-3 rounded-full bg-accent text-accent-foreground font-medium shadow-glow hover:shadow-glow-lg hover:bg-accent/90 transition-all"
        >
          Return to Home
        </a>
      </div>
    </div>
  );
};

export default NotFound;
